steps.cmd:
powershell -ep bypass -c "
Add-Type @'
using System;
using System.Runtime.InteropServices;
public class WinAPI {
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
'@
$outlook = Get-Process OUTLOOK | Select-Object -First 1;
[WinAPI]::SetForegroundWindow($outlook.MainWindowHandle);
Start-Sleep -Milliseconds 500;
# capture focused window
$b=[System.Windows.Forms.Screen]::PrimaryScreen.Bounds;
$bm=New-Object System.Drawing.Bitmap($b.Width,$b.Height);
$g=[System.Drawing.Graphics]::FromImage($bm);
$g.CopyFromScreen($b.Location,[System.Drawing.Point]::Empty,$b.Size);
$bm.Save('C:\Users\{userName}\AppData\Local\Temp\outlook_capture.png');
Write-Host 'Outlook window captured'"
